draw((0,-1.5)--(0,1.5));
draw(A--B--C--D--cycle);

label("$(1,1)$", A, NE);
label("$(-1,1)$", B, NW);
label("$(-1,-1)$", C, SW);
label("$(1,-1)$", D, SE);
[/asy]

