// calculate intersection of line and plane
// p = point on line
// d = direction of line
// q = point in plane
// n = normal to plane
triple lineintersectplan(triple p, triple d, triple q, triple n)
{
  return (p + dot(n,q - p)/dot(n,d)*d);
}

